// checkRemoteMetadata checks if checkpoint metadata exists on the remote and
// automatically fetches it if available. Tries origin first, then the checkpoint_remote
// if configured (for repos that store checkpoints in a separate repository).
func checkRemoteMetadata(ctx context.Context, checkpointID id.CheckpointID) error {
	logCtx := logging.WithComponent(ctx, "resume.checkRemoteMetadata")

	// Open a fresh repo to avoid stale packfile index issues
	repo, repoErr := openRepository(ctx)
	if repoErr != nil {
		logging.Warn(logCtx, "failed to open repository for remote check",
			slog.String("error", repoErr.Error()),
		)
		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
		return nil
	}

	// Try origin's remote-tracking branch first
	if metadata, err := tryReadCheckpointFromTree(ctx, strategy.GetRemoteMetadataBranchTree(repo), repo, checkpointID); err == nil {
		return resumeSession(ctx, os.Stdout, os.Stderr, metadata, false)
	}

	// Try fetching from checkpoint_remote if configured
	if fetchErr := FetchMetadataFromCheckpointRemote(ctx); fetchErr == nil {
		freshRepo, freshErr := openRepository(ctx)
		if freshErr == nil {
			metadataTree, treeErr := strategy.GetMetadataBranchTree(freshRepo)
			if treeErr == nil {
				if metadata, err := tryReadCheckpointFromTree(ctx, metadataTree, nil, freshRepo, checkpointID); err == nil {
					return resumeSession(ctx, os.Stdout, os.Stderr, metadata, false)
				}
			}
		}
	} else {
		logging.Debug(logCtx, "checkpoint remote fetch failed or not configured",
			slog.String("error", fetchErr.Error()),
		)
	}

	// Nothing worked — print helpful error message
	_, hasCheckpointRemote := strategy.ResolveCheckpointRemoteURL(ctx)
	if hasCheckpointRemote {
		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but its metadata could not be fetched from the checkpoint remote.\n", checkpointID)
		fmt.Fprintf(os.Stderr, "Ensure you have access to the checkpoint remote configured in .entire/settings.json.\n")
	} else {
		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but the entire/checkpoints/v1 branch is not available locally or on the remote.\n", checkpointID)
		fmt.Fprintf(os.Stderr, "This can happen if the metadata branch was not pushed. Try:\n")
		fmt.Fprintf(os.Stderr, "  git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
	}
	return nil
}

// tryReadCheckpointFromTree attempts to read checkpoint metadata from a tree.
// The tree can be nil (returns error), and repoForBlobs is the repo used for blob fetching.
func tryReadCheckpointFromTree(ctx context.Context, tree *object.Tree, treeErr error, repoForBlobs *git.Repository, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
	if treeErr != nil {
		return nil, treeErr
	}
	cpSubtree, cpErr := tree.Tree(checkpointID.Path())
	if cpErr != nil {
		return nil, cpErr
	}
	ft := checkpoint.NewFetchingTree(ctx, cpSubtree, repoForBlobs.Storer, FetchBlobsByHash)
	if _, pfErr := ft.PreFetch(); pfErr != nil {
		logging.Debug(ctx, "tryReadCheckpointFromTree: PreFetch failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("error", pfErr.Error()),
		)
	}
	return strategy.ReadCheckpointMetadataFromSubtree(ft, checkpointID.Path())
}

