  1→package cli
  2→
  3→import (
  4→	"bytes"
  5→	"context"
  6→	"errors"
  7→	"fmt"
  8→	"log/slog"
  9→	"os"
 10→	"os/exec"
 11→	"strings"
 12→	"time"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/logging"
 15→	"github.com/entireio/cli/cmd/entire/cli/paths"
 16→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 17→
 18→	"github.com/go-git/go-git/v6"
 19→	"github.com/go-git/go-git/v6/plumbing"
 20→)
 21→
 22→// openRepository opens the git repository with linked worktree support enabled.
 23→// This is a convenience wrapper around strategy.OpenRepository() for use in the CLI package.
 24→func openRepository(ctx context.Context) (*git.Repository, error) {
 25→	repo, err := strategy.OpenRepository(ctx)
 26→	if err != nil {
 27→		return nil, fmt.Errorf("failed to open repository: %w", err)
 28→	}
 29→	return repo, nil
 30→}
 31→
 32→// GitAuthor represents the git user configuration
 33→type GitAuthor struct {
 34→	Name  string
 35→	Email string
 36→}
 37→
 38→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 39→// It checks local config first, then falls back to global config.
 40→// If go-git can't find the config, it falls back to using the git command.
 41→// Returns fallback defaults if no user is configured anywhere.
 42→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 43→	repo, err := openRepository(ctx)
 44→	if err != nil {
 45→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 46→	}
 47→
 48→	name, email := strategy.GetGitAuthorFromRepo(repo)
 49→
 50→	// If go-git returned defaults, try using git command as fallback
 51→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
 52→	// non-standard config locations, or environment issues in hook contexts)
 53→	if name == "Unknown" {
 54→		if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
 55→			name = gitName
 56→		}
 57→	}
 58→	if email == "unknown@local" {
 59→		if gitEmail := getGitConfigValue(ctx, "user.email"); gitEmail != "" {
 60→			email = gitEmail
 61→		}
 62→	}
 63→
 64→	return &GitAuthor{
 65→		Name:  name,
 66→		Email: email,
 67→	}, nil
 68→}
 69→
 70→// getGitConfigValue retrieves a git config value using the git command.
 71→// Returns empty string if the value is not set or on error.
 72→func getGitConfigValue(ctx context.Context, key string) string {
 73→	cmd := exec.CommandContext(ctx, "git", "config", "--get", key)
 74→	output, err := cmd.Output()
 75→	if err != nil {
 76→		return ""
 77→	}
 78→	return strings.TrimSpace(string(output))
 79→}
 80→
 81→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 82→// It determines the default branch by:
 83→// 1. Checking the remote origin's HEAD reference
 84→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 85→// Returns (isDefault, branchName, error)
 86→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 87→	repo, err := openRepository(ctx)
 88→	if err != nil {
 89→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 90→	}
 91→
 92→	// Get current branch
 93→	head, err := repo.Head()
 94→	if err != nil {
 95→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 96→	}
 97→
 98→	if !head.Name().IsBranch() {
 99→		// Detached HEAD - not on any branch
100→		return false, "", nil
101→	}
102→
103→	currentBranch := head.Name().Short()
104→
105→	// Try to get default branch from remote origin's HEAD
106→	defaultBranch := getDefaultBranchFromRemote(repo)
107→
108→	// If we couldn't determine from remote, use common defaults
109→	if defaultBranch == "" {
110→		// Check if current branch is a common default name
111→		if currentBranch == "main" || currentBranch == "master" {
112→			return true, currentBranch, nil
113→		}
114→		return false, currentBranch, nil
115→	}
116→
117→	return currentBranch == defaultBranch, currentBranch, nil
118→}
119→
120→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
121→// Returns empty string if unable to determine.
122→func getDefaultBranchFromRemote(repo *git.Repository) string {
123→	// Try to get the symbolic reference for origin/HEAD
124→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
125→	if err == nil && ref != nil {
126→		// ref.Target() gives us something like "refs/remotes/origin/main"
127→		target := ref.Target().String()
128→		if strings.HasPrefix(target, "refs/remotes/origin/") {
129→			return strings.TrimPrefix(target, "refs/remotes/origin/")
130→		}
131→	}
132→
133→	// Fallback: check if origin/main or origin/master exists
134→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
135→		return "main"
136→	}
137→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
138→		return "master"
139→	}
140→
141→	return ""
142→}
143→
144→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
145→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
146→// skip the operation to avoid polluting main/master history.
147→// If the branch cannot be determined, returns (false, "") to allow the operation.
148→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
149→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
150→	if err != nil {
151→		// If we can't determine, allow the operation
152→		return false, ""
153→	}
154→	return isDefault, branchName
155→}
156→
157→// GetCurrentBranch returns the name of the current branch.
158→// Returns an error if in detached HEAD state or if not in a git repository.
159→func GetCurrentBranch(ctx context.Context) (string, error) {
160→	repo, err := openRepository(ctx)
161→	if err != nil {
162→		return "", fmt.Errorf("failed to open git repository: %w", err)
163→	}
164→
165→	head, err := repo.Head()
166→	if err != nil {
167→		return "", fmt.Errorf("failed to get HEAD: %w", err)
168→	}
169→
170→	if !head.Name().IsBranch() {
171→		return "", errors.New("not on a branch (detached HEAD)")
172→	}
173→
174→	return head.Name().Short(), nil
175→}
176→
177→// GetMergeBase finds the common ancestor (merge-base) between two branches.
178→// Returns the hash of the merge-base commit.
179→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
180→	repo, err := openRepository(ctx)
181→	if err != nil {
182→		return nil, fmt.Errorf("failed to open git repository: %w", err)
183→	}
184→
185→	// Resolve branch references
186→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
187→	if err != nil {
188→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
189→	}
190→
191→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
192→	if err != nil {
193→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
194→	}
195→
196→	// Get commit objects
197→	commit1, err := repo.CommitObject(ref1.Hash())
198→	if err != nil {
199→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
200→	}
201→
202→	commit2, err := repo.CommitObject(ref2.Hash())
203→	if err != nil {
204→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
205→	}
206→
207→	// Find common ancestor
208→	mergeBase, err := commit1.MergeBase(commit2)
209→	if err != nil {
210→		return nil, fmt.Errorf("failed to find merge base: %w", err)
211→	}
212→
213→	if len(mergeBase) == 0 {
214→		return nil, errors.New("no common ancestor found")
215→	}
216→
217→	hash := mergeBase[0].Hash
218→	return &hash, nil
219→}
