221→// HasUncommittedChanges checks if there are any uncommitted changes in the repository.
222→// This includes staged changes, unstaged changes, and untracked files.
223→// Uses git CLI instead of go-git because go-git doesn't respect global gitignore
224→// (core.excludesfile) which can cause false positives for globally ignored files.
225→func HasUncommittedChanges(ctx context.Context) (bool, error) {
226→	cmd := exec.CommandContext(ctx, "git", "status", "--porcelain")
227→	output, err := cmd.Output()
228→	if err != nil {
229→		return false, fmt.Errorf("failed to get git status: %w", err)
230→	}
231→
232→	// If output is empty, there are no changes
233→	return len(strings.TrimSpace(string(output))) > 0, nil
234→}
