236→// findNewUntrackedFiles finds files that are newly untracked (not in pre-existing list)
237→func findNewUntrackedFiles(current, preExisting []string) []string {
238→	preExistingSet := make(map[string]bool)
239→	for _, file := range preExisting {
240→		preExistingSet[file] = true
241→	}
242→
243→	var newFiles []string
244→	for _, file := range current {
245→		if !preExistingSet[file] {
246→			newFiles = append(newFiles, file)
247→		}
248→	}
249→	return newFiles
250→}
