252→// BranchExistsOnRemote checks if a branch exists on the origin remote.
253→// First checks local remote-tracking refs, then queries the actual remote
254→// via git ls-remote in case local refs are stale (e.g., after a fresh clone
255→// that didn't fetch all branches).
256→func BranchExistsOnRemote(ctx context.Context, branchName string) (bool, error) {
257→	repo, err := openRepository(ctx)
258→	if err != nil {
259→		return false, fmt.Errorf("failed to open git repository: %w", err)
260→	}
261→
262→	// Check for remote reference: refs/remotes/origin/<branchName>
263→	_, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
264→	if err == nil {
265→		return true, nil
266→	}
267→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
268→		return false, fmt.Errorf("failed to check remote branch: %w", err)
269→	}
270→
271→	// Local remote-tracking ref not found — query the actual remote.
272→	lsCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
273→	defer cancel()
274→
275→	lsCmd := exec.CommandContext(lsCtx, "git", "ls-remote", "--heads", "origin", "refs/heads/"+branchName)
276→	output, lsErr := lsCmd.Output()
277→	if lsErr != nil {
278→		// ls-remote failed (no network, no remote, etc.) — treat as not found
279→		return false, nil
280→	}
281→
282→	return len(bytes.TrimSpace(output)) > 0, nil
283→}
