329→// FetchAndCheckoutRemoteBranch fetches a branch from origin and creates a local tracking branch.
330→// Uses git CLI instead of go-git for fetch because go-git doesn't use credential helpers,
331→// which breaks HTTPS URLs that require authentication.
332→func FetchAndCheckoutRemoteBranch(ctx context.Context, branchName string) error {
333→	// Validate branch name before using in shell command (branchName comes from user CLI input)
334→	if err := ValidateBranchName(ctx, branchName); err != nil {
335→		return err
336→	}
337→
338→	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
339→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
340→	defer cancel()
341→
342→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
343→
344→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
345→	if output, err := fetchCmd.CombinedOutput(); err != nil {
346→		if ctx.Err() == context.DeadlineExceeded {
347→			return errors.New("fetch timed out after 2 minutes")
348→		}
349→		return fmt.Errorf("failed to fetch branch from origin: %s: %w", strings.TrimSpace(string(output)), err)
350→	}
351→
352→	repo, err := openRepository(ctx)
353→	if err != nil {
354→		return fmt.Errorf("failed to open repository: %w", err)
355→	}
356→
357→	// Get the remote branch reference
358→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
359→	if err != nil {
360→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
361→	}
362→
363→	// Create local branch pointing to the same commit
364→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
365→	err = repo.Storer.SetReference(localRef)
366→	if err != nil {
367→		return fmt.Errorf("failed to create local branch: %w", err)
368→	}
369→
370→	// Checkout the new local branch
371→	return CheckoutBranch(ctx, branchName)
372→}
