511→// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
512→// Uses "git fetch origin <hash>" which goes through normal credential helpers,
513→// unlike fetch-pack which bypasses them. Requires the server to support
514→// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
515→//
516→// If fetching by hash fails, falls back to a full metadata branch fetch.
517→func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
518→	if len(hashes) == 0 {
519→		return nil
520→	}
521→
522→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
523→	defer cancel()
524→
525→	// Build fetch args: "git fetch origin <hash1> <hash2> ..."
526→	// This uses the normal transport + credential helpers, unlike fetch-pack.
527→	args := []string{"fetch", "--no-write-fetch-head", "origin"}
528→	for _, h := range hashes {
529→		args = append(args, h.String())
530→	}
531→
532→	fetchCmd := exec.CommandContext(ctx, "git", args...)
533→	if _, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
534→		logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
535→			slog.Int("blob_count", len(hashes)),
536→			slog.String("error", fetchErr.Error()),
537→		)
538→		// Fallback: full metadata branch fetch (pack negotiation skips already-local objects)
539→		if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
540→			return fmt.Errorf("fetch-by-hash failed: %w; fallback fetch also failed: %w",
541→				fetchErr, fallbackErr)
542→		}
543→	}
544→
545→	return nil
546→}
