588→func promptResumeFromOlderCheckpoint() (bool, error) {
589→	var confirmed bool
590→
591→	form := NewAccessibleForm(
592→		huh.NewGroup(
593→			huh.NewConfirm().
594→				Title("Resume from this older checkpoint?").
595→				Value(&confirmed),
596→		),
597→	)
598→
599→	if err := form.Run(); err != nil {
600→		if errors.Is(err, huh.ErrUserAborted) {
601→			return false, nil
602→		}
603→		return false, fmt.Errorf("failed to get confirmation: %w", err)
604→	}
605→
606→	return confirmed, nil
607→}
