609→// checkRemoteMetadata checks if checkpoint metadata exists on the remote and
610→// automatically fetches it if available. When a checkpoint_remote is configured,
611→// fetches from there (that's where checkpoints live). Otherwise falls back to origin.
612→func checkRemoteMetadata(ctx context.Context, checkpointID id.CheckpointID) error {
613→	logCtx := logging.WithComponent(ctx, "resume.checkRemoteMetadata")
614→
615→	// Open a fresh repo to avoid stale packfile index issues
616→	repo, repoErr := openRepository(ctx)
617→	if repoErr != nil {
618→		logging.Warn(logCtx, "failed to open repository for remote check",
619→			slog.String("error", repoErr.Error()),
620→		)
621→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
622→		return nil
623→	}
624→
625→	// Try checkpoint_remote first if configured (that's where checkpoints are stored)
626→	if fetchErr := FetchMetadataFromCheckpointRemote(ctx); fetchErr == nil {
627→		freshRepo, freshErr := openRepository(ctx)
628→		if freshErr == nil {
629→			if metadataTree, treeErr := strategy.GetMetadataBranchTree(freshRepo); treeErr == nil {
630→				if metadata, err := tryReadCheckpointFromTree(ctx, metadataTree, freshRepo, checkpointID); err == nil {
631→					return resumeSession(ctx, os.Stdout, os.Stderr, metadata, false)
632→				}
633→			}
634→		}
635→	} else {
636→		logging.Debug(logCtx, "checkpoint remote fetch failed or not configured",
637→			slog.String("error", fetchErr.Error()),
638→		)
639→	}
640→
641→	// Fall back to origin's remote-tracking branch
642→	if remoteTree, treeErr := strategy.GetRemoteMetadataBranchTree(repo); treeErr == nil {
643→		if metadata, err := tryReadCheckpointFromTree(ctx, remoteTree, repo, checkpointID); err == nil {
644→			return resumeSession(ctx, os.Stdout, os.Stderr, metadata, false)
645→		}
646→	}
647→
648→	// Nothing worked — print helpful error message
649→	_, hasCheckpointRemote := strategy.ResolveCheckpointRemoteURL(ctx)

