 38→// GetGitAuthor retrieves the git user.name and user.email from the repository config.
 39→// It checks local config first, then falls back to global config.
 40→// If go-git can't find the config, it falls back to using the git command.
 41→// Returns fallback defaults if no user is configured anywhere.
 42→func GetGitAuthor(ctx context.Context) (*GitAuthor, error) {
 43→	repo, err := openRepository(ctx)
 44→	if err != nil {
 45→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 46→	}
 47→
 48→	name, email := strategy.GetGitAuthorFromRepo(repo)
 49→
 50→	// If go-git returned defaults, try using git command as fallback
 51→	// This handles cases where go-git can't find the config (e.g., different HOME paths,
 52→	// non-standard config locations, or environment issues in hook contexts)
 53→	if name == "Unknown" {
 54→		if gitName := getGitConfigValue(ctx, "user.name"); gitName != "" {
 55→			name = gitName
 56→		}
 57→	}
 58→	if email == "unknown@local" {
