 81→// IsOnDefaultBranch checks if the repository is currently on the default branch.
 82→// It determines the default branch by:
 83→// 1. Checking the remote origin's HEAD reference
 84→// 2. Falling back to common names (main, master) if remote HEAD is unavailable
 85→// Returns (isDefault, branchName, error)
 86→func IsOnDefaultBranch(ctx context.Context) (bool, string, error) {
 87→	repo, err := openRepository(ctx)
 88→	if err != nil {
 89→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 90→	}
 91→
 92→	// Get current branch
 93→	head, err := repo.Head()
 94→	if err != nil {
 95→		return false, "", fmt.Errorf("failed to get HEAD: %w", err)
 96→	}
 97→
 98→	if !head.Name().IsBranch() {
 99→		// Detached HEAD - not on any branch
100→		return false, "", nil
101→	}
102→
103→	currentBranch := head.Name().Short()
104→
105→	// Try to get default branch from remote origin's HEAD
106→	defaultBranch := getDefaultBranchFromRemote(repo)
107→
108→	// If we couldn't determine from remote, use common defaults
109→	if defaultBranch == "" {
110→		// Check if current branch is a common default name
111→		if currentBranch == "main" || currentBranch == "master" {
112→			return true, currentBranch, nil
113→		}
114→		return false, currentBranch, nil
115→	}
116→
117→	return currentBranch == defaultBranch, currentBranch, nil
118→}
