120→// getDefaultBranchFromRemote tries to determine the default branch from the origin remote.
121→// Returns empty string if unable to determine.
122→func getDefaultBranchFromRemote(repo *git.Repository) string {
123→	// Try to get the symbolic reference for origin/HEAD
124→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), true)
125→	if err == nil && ref != nil {
126→		// ref.Target() gives us something like "refs/remotes/origin/main"
127→		target := ref.Target().String()
128→		if strings.HasPrefix(target, "refs/remotes/origin/") {
129→			return strings.TrimPrefix(target, "refs/remotes/origin/")
130→		}
131→	}
132→
133→	// Fallback: check if origin/main or origin/master exists
134→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "main"), true); err == nil {
135→		return "main"
136→	}
137→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "master"), true); err == nil {
138→		return "master"
139→	}
140→
141→	return ""
142→}
