144→// ShouldSkipOnDefaultBranch checks if we're on the default branch.
145→// Returns (shouldSkip, branchName). If shouldSkip is true, the caller should
146→// skip the operation to avoid polluting main/master history.
147→// If the branch cannot be determined, returns (false, "") to allow the operation.
148→func ShouldSkipOnDefaultBranch(ctx context.Context) (bool, string) {
149→	isDefault, branchName, err := IsOnDefaultBranch(ctx)
150→	if err != nil {
151→		// If we can't determine, allow the operation
152→		return false, ""
153→	}
