177→// GetMergeBase finds the common ancestor (merge-base) between two branches.
178→// Returns the hash of the merge-base commit.
179→func GetMergeBase(ctx context.Context, branch1, branch2 string) (*plumbing.Hash, error) {
180→	repo, err := openRepository(ctx)
181→	if err != nil {
182→		return nil, fmt.Errorf("failed to open git repository: %w", err)
183→	}
184→
185→	// Resolve branch references
186→	ref1, err := repo.Reference(plumbing.NewBranchReferenceName(branch1), true)
187→	if err != nil {
188→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch1, err)
189→	}
190→
191→	ref2, err := repo.Reference(plumbing.NewBranchReferenceName(branch2), true)
192→	if err != nil {
193→		return nil, fmt.Errorf("failed to resolve branch %s: %w", branch2, err)
194→	}
195→
196→	// Get commit objects
197→	commit1, err := repo.CommitObject(ref1.Hash())
198→	if err != nil {
199→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch1, err)
200→	}
201→
202→	commit2, err := repo.CommitObject(ref2.Hash())
203→	if err != nil {
204→		return nil, fmt.Errorf("failed to get commit for %s: %w", branch2, err)
205→	}
206→
207→	// Find common ancestor
208→	mergeBase, err := commit1.MergeBase(commit2)
209→	if err != nil {
210→		return nil, fmt.Errorf("failed to find merge base: %w", err)
211→	}
212→
213→	if len(mergeBase) == 0 {
214→		return nil, errors.New("no common ancestor found")
215→	}
216→
217→	hash := mergeBase[0].Hash
218→	return &hash, nil
219→}
