305→// deletes untracked files (see https://github.com/go-git/go-git/issues/970).
306→// Should be switched back to go-git once we upgrade to go-git v6
307→// Returns an error if the ref doesn't exist or checkout fails.
308→func CheckoutBranch(ctx context.Context, ref string) error {
309→	if strings.HasPrefix(ref, "-") {
310→		return fmt.Errorf("checkout failed: invalid ref %q", ref)
