457→// FetchMetadataFromCheckpointRemote fetches the entire/checkpoints/v1 branch from the
458→// configured checkpoint_remote URL and updates the local branch.
459→// This is used when checkpoints are stored in a separate repo (e.g., entireio/cli-checkpoints)
460→// and the local metadata branch is missing or stale.
461→// Returns an error if the fetch fails or no checkpoint_remote is configured.
462→func FetchMetadataFromCheckpointRemote(ctx context.Context) error {
463→	checkpointURL, ok := strategy.ResolveCheckpointRemoteURL(ctx)
464→	if !ok {
465→		return errors.New("no checkpoint_remote configured")
466→	}
467→
468→	branchName := paths.MetadataBranchName
469→
470→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
471→	defer cancel()
472→
473→	// Fetch to a temp ref to avoid polluting the remote-tracking namespace.
474→	tmpRef := "refs/entire-fetch-tmp/" + branchName
475→	refSpec := fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
476→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "--no-tags", checkpointURL, refSpec)
477→	fetchCmd.Stdin = nil
478→	fetchCmd.Env = append(os.Environ(),
479→		"GIT_TERMINAL_PROMPT=0",
480→	)
481→	if output, err := fetchCmd.CombinedOutput(); err != nil {
482→		if ctx.Err() == context.DeadlineExceeded {
483→			return errors.New("checkpoint remote fetch timed out after 2 minutes")
484→		}
485→		return fmt.Errorf("failed to fetch %s from checkpoint remote: %s: %w", branchName, strings.TrimSpace(string(output)), err)
486→	}
487→
488→	repo, err := openRepository(ctx)
489→	if err != nil {
490→		return fmt.Errorf("failed to open repository: %w", err)
491→	}
492→
493→	// Get the fetched ref
494→	fetchedRef, err := repo.Reference(plumbing.ReferenceName(tmpRef), true)
495→	if err != nil {
496→		return fmt.Errorf("branch '%s' not found after fetch from checkpoint remote: %w", branchName, err)
497→	}
498→
499→	// Create or update local branch pointing to the fetched commit
500→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), fetchedRef.Hash())
501→	if err := repo.Storer.SetReference(localRef); err != nil {
502→		return fmt.Errorf("failed to create local %s branch: %w", branchName, err)
503→	}
504→
505→	// Clean up the temp ref (best-effort)
506→	_ = repo.Storer.RemoveReference(plumbing.ReferenceName(tmpRef)) //nolint:errcheck // cleanup is best-effort
507→
508→	return nil
509→}
