661→// tryReadCheckpointFromTree attempts to read checkpoint metadata from a metadata tree.
662→func tryReadCheckpointFromTree(ctx context.Context, tree *object.Tree, repo *git.Repository, checkpointID id.CheckpointID) (*strategy.CheckpointInfo, error) {
663→	cpSubtree, cpErr := tree.Tree(checkpointID.Path())
664→	if cpErr != nil {
665→		return nil, fmt.Errorf("checkpoint subtree not found: %w", cpErr)
666→	}
667→	ft := checkpoint.NewFetchingTree(ctx, cpSubtree, repo.Storer, FetchBlobsByHash)
668→	if _, pfErr := ft.PreFetch(); pfErr != nil {
669→		logging.Debug(ctx, "tryReadCheckpointFromTree: PreFetch failed",
670→			slog.String("checkpoint_id", checkpointID.String()),
671→			slog.String("error", pfErr.Error()),
672→		)
673→	}
674→	metadata, err := strategy.ReadCheckpointMetadataFromSubtree(ft, checkpointID.Path())
675→	if err != nil {
676→		return nil, fmt.Errorf("failed to read checkpoint metadata: %w", err)
677→	}
678→	return metadata, nil
679→}
