681→// resumeSession restores and displays the resume command for a specific session.
682→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
683→// If force is false, prompts for confirmation when local logs have newer timestamps.
684→// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
685→// and to support both local and remote metadata trees.
686→func resumeSession(ctx context.Context, w, errW io.Writer, metadata *strategy.CheckpointInfo, force bool) error {
687→	checkpointID := metadata.CheckpointID
688→	sessionID := metadata.SessionID
689→
690→	// Resolve agent from checkpoint metadata (same as rewind)
691→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
692→	if err != nil {
693→		return fmt.Errorf("failed to resolve agent: %w", err)
694→	}
695→
696→	// Initialize logging context with agent
697→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
698→
699→	logging.Debug(logCtx, "resume session started",
700→		slog.String("checkpoint_id", checkpointID.String()),
701→		slog.String("session_id", sessionID),
702→	)
703→
704→	// Get worktree root for session directory lookup
705→	repoRoot, err := paths.WorktreeRoot(ctx)
706→	if err != nil {
707→		return fmt.Errorf("failed to get worktree root: %w", err)
708→	}
709→
710→	sessionDir, err := ag.GetSessionDir(repoRoot)
711→	if err != nil {
712→		return fmt.Errorf("failed to determine session directory: %w", err)
713→	}
714→
715→	// Create directory if it doesn't exist
716→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
717→		return fmt.Errorf("failed to create session directory: %w", err)
718→	}
719→
720→	// Get strategy and restore sessions using full checkpoint data
721→	strat := GetStrategy(ctx)
722→
723→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
724→	// Create a logs-only rewind point with Agent populated (same as rewind)
725→	point := strategy.RewindPoint{
726→		IsLogsOnly:   true,
727→		CheckpointID: checkpointID,
728→		Agent:        metadata.Agent,
729→	}
730→
731→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
732→	if restoreErr != nil || len(sessions) == 0 {
733→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
734→		return resumeSingleSession(ctx, w, errW, ag, sessionID, checkpointID, repoRoot, force)
735→	}
736→
737→	logging.Debug(logCtx, "resume session completed",
738→		slog.String("checkpoint_id", checkpointID.String()),
739→		slog.Int("session_count", len(sessions)),
740→	)
741→
742→	return displayRestoredSessions(w, sessions)
743→}
