 28→// WriteTaskCheckpoint writes the checkpoint.json file to the task metadata directory.
 29→// Creates the directory if it doesn't exist.
 30→// Uses os.Root for traversal-resistant file writes within the metadata directory.
 31→func WriteTaskCheckpoint(taskMetadataDir string, checkpoint *TaskCheckpoint) error {
 32→	// Create directory if it doesn't exist (MkdirAll not available on os.Root)
 33→	if err := os.MkdirAll(taskMetadataDir, 0o750); err != nil {
 34→		return fmt.Errorf("failed to create task metadata directory: %w", err)
 35→	}
 36→
 37→	data, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
 38→	if err != nil {
 39→		return fmt.Errorf("failed to marshal checkpoint: %w", err)
 40→	}
 41→
 42→	// Use os.Root scoped to the metadata directory for traversal-resistant write
 43→	root, err := os.OpenRoot(taskMetadataDir)
 44→	if err != nil {
 45→		return fmt.Errorf("failed to open task metadata directory: %w", err)
 46→	}
 47→	defer root.Close()
 48→
 49→	if err := osroot.WriteFile(root, paths.CheckpointFileName, data, 0o600); err != nil {
 50→		return fmt.Errorf("failed to write checkpoint file: %w", err)
 51→	}
 52→
 53→	return nil
 54→}
