 56→// ReadTaskCheckpoint reads the checkpoint file from the task metadata directory.
 57→// Uses os.Root for traversal-resistant file reads within the metadata directory.
 58→func ReadTaskCheckpoint(taskMetadataDir string) (*TaskCheckpoint, error) {
 59→	root, err := os.OpenRoot(taskMetadataDir)
 60→	if err != nil {
 61→		return nil, fmt.Errorf("failed to open task metadata directory: %w", err)
 62→	}
 63→	defer root.Close()
 64→
 65→	data, err := osroot.ReadFile(root, paths.CheckpointFileName)
 66→	if err != nil {
 67→		return nil, fmt.Errorf("failed to read checkpoint file: %w", err)
 68→	}
 69→
 70→	var checkpoint TaskCheckpoint
 71→	if err := json.Unmarshal(data, &checkpoint); err != nil {
 72→		return nil, fmt.Errorf("failed to unmarshal checkpoint: %w", err)
 73→	}
 74→
 75→	return &checkpoint, nil
 76→}
