284→// BranchExistsLocally checks if a local branch exists.
285→func BranchExistsLocally(ctx context.Context, branchName string) (bool, error) {
286→	repo, err := openRepository(ctx)
287→	if err != nil {
288→		return false, fmt.Errorf("failed to open git repository: %w", err)
289→	}
290→
291→	_, err = repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
292→	if err != nil {
293→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
294→			return false, nil
295→		}
296→		return false, fmt.Errorf("failed to check branch: %w", err)
297→	}
298→
299→	return true, nil
300→}
