471→// FetchBlobsByHash fetches specific blob objects from the remote by their SHA-1 hashes.
472→// Uses "git fetch origin <hash>" which goes through normal credential helpers,
473→// unlike fetch-pack which bypasses them. Requires the server to support
474→// uploadpack.allowReachableSHA1InWant (GitHub, GitLab, Bitbucket all do).
475→//
476→// If fetching by hash fails, falls back to a full metadata branch fetch.
477→func FetchBlobsByHash(ctx context.Context, hashes []plumbing.Hash) error {
478→	if len(hashes) == 0 {
479→		return nil
480→	}
481→
482→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
483→	defer cancel()
484→
485→	// Build fetch args: "git fetch origin <hash1> <hash2> ..."
486→	// This uses the normal transport + credential helpers, unlike fetch-pack.
487→	args := []string{"fetch", "--no-write-fetch-head", "origin"}
488→	for _, h := range hashes {
489→		args = append(args, h.String())
490→	}
491→
492→	fetchCmd := exec.CommandContext(ctx, "git", args...)
493→	if _, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
494→		logging.Debug(ctx, "fetch-by-hash failed, falling back to full metadata fetch",
495→			slog.Int("blob_count", len(hashes)),
496→			slog.String("error", fetchErr.Error()),
497→		)
498→		// Fallback: full metadata branch fetch (pack negotiation skips already-local objects)
499→		if fallbackErr := FetchMetadataBranch(ctx); fallbackErr != nil {
500→			return fmt.Errorf("fetch-by-hash failed: %w; fallback fetch also failed: %w",
501→				fetchErr, fallbackErr)
502→		}
503→	}
504→
505→	return nil
506→}
