383→	// Fetch failures are not fatal: push will create it on the remote when it succeeds.
384→	if err := FetchMetadataBranch(ctx, remoteURL); err != nil {
385→		return nil //nolint:nilerr // Fetch failure is expected when remote is unreachable or branch doesn't exist yet
