414→// FetchMetadataTreeOnly fetches the tip of the entire/checkpoints/v1 branch
415→// from origin with --depth=1 --filter=blob:none, downloading only the latest
416→// commit and its tree objects (no blobs, no history).
417→// After this call, tree navigation via go-git works but blob reads will fail
418→// for objects that weren't previously fetched.
419→// Uses git CLI for credential helper support.
420→func FetchMetadataTreeOnly(ctx context.Context) error {
421→	branchName := paths.MetadataBranchName
422→
423→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
424→	defer cancel()
425→
426→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
427→
428→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", "--depth=1", "--filter=blob:none", "origin", refSpec)
429→	if output, err := fetchCmd.CombinedOutput(); err != nil {
430→		if ctx.Err() == context.DeadlineExceeded {
431→			return errors.New("treeless fetch timed out after 2 minutes")
432→		}
433→		return fmt.Errorf("failed to treeless-fetch %s from origin: %s: %w", branchName, strings.TrimSpace(string(output)), err)
434→	}
435→
436→	repo, err := openRepository(ctx)
437→	if err != nil {
438→		return fmt.Errorf("failed to open repository: %w", err)
439→	}
440→
441→	// Get the remote branch reference
442→	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
443→	if err != nil {
444→		return fmt.Errorf("branch '%s' not found on origin: %w", branchName, err)
445→	}
446→
447→	// Create or update local branch pointing to the same commit
448→	localRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
449→	if err := repo.Storer.SetReference(localRef); err != nil {
450→		return fmt.Errorf("failed to create local %s branch: %w", branchName, err)
451→	}
452→
453→	return nil
454→}
